// 原rescue/move_local边界；个人货损、位置和行动改种均经A同候选基元，不重复钱包。
#include "travel.hpp"
#include <algorithm>
namespace hanmo::resident {
// 原救助首错不经过一般ActorUnavailable守卫；军团必须先真实返营。
Status preview_rescue(const CommonRead& common,const TravelState& state,const TravelCatalog& catalog,const TravelServices& services,const StableId& actor_id){auto field=common.field_battle_bound(actor_id);if(!field.ok)return {false,{},field.error};if(field.value)return {false,{},common_failure("FieldBattleMovementBlocked",actor_id).error};auto army=services.active_army(actor_id);if(!army.ok)return {false,{},army.error};if(army.value)return common_failure("ArmyNotReturned");const auto* actor=common.actor(actor_id);const auto* action=actor?common.action(actor->action_id):nullptr;if(!action||action->kind!="travel")return common_failure("NotTravelling");StableId payer;Integer cost=0;if(auto p=state.road_actions.find(action->id)){auto location=std::get_if<OnRouteLocation>(&actor->location);if(!location)return common_failure("InvalidTravelAction",action->id,ErrorKind::internal);payer=p->payer_wallet_id;cost=road_next_cost(catalog,services,*action,*p,*location);}else if(auto p=state.actions.find(action->id)){payer=p->payer_wallet_id;cost=p->money_per_tick;}else return common_failure("InvalidTravelAction",action->id,ErrorKind::internal);auto funds=common.spendable(payer);if(!funds.ok)return {false,{},funds.error};if(funds.value>=cost)return common_failure("NotStranded");return common_success();}
// 救助保留原行动ID、人物占用和start_tick，只替换kind/params与期限。
Status begin_rescue(CommonWrite& common,TravelState& state,const StableId& actor_id,std::optional<TravelRescueReplacementDraft>* replacement){auto field=common.field_battle_bound(actor_id);if(!field.ok)return {false,{},field.error};if(field.value)return {false,{},common_failure("FieldBattleMovementBlocked",actor_id).error};if(replacement)replacement->reset();const auto* actor=common.actor(actor_id);const auto* original=actor?common.action(actor->action_id):nullptr;if(!actor||!original||original->kind!="travel")return common_failure("NotTravelling");auto action=*original;StableId origin;if(auto* p=std::get_if<WildernessLocation>(&actor->location))origin=p->origin;else if(auto* p=std::get_if<OnRouteLocation>(&actor->location))origin=p->origin;else return common_failure("NotTravelling");
    // 原活动载荷会立即删除，必须在这里取唯一实际原件；缺源只拒选中捕获，不伪造默认道路。
    std::optional<TravelRescueReplacementDraft> draft;if(replacement){const auto* terrain=state.actions.find(action.id);const auto* road=state.road_actions.find(action.id);if(bool(terrain)==bool(road))return common_failure("TravelRescueOriginalPayloadRequired",action.id);draft.emplace();draft->original_action=action;draft->source_tick=common.tick();draft->original_location=actor->location;if(terrain)draft->original_travel=*terrain;else draft->original_travel=*road;draft->rescue={origin};}
    ActionMutation change;change.action=action;change.action_kind=StableId{"rescue"};change.remaining_ticks=2;auto changed=common.apply_action(change);if(!changed.ok)return changed;state.actions.erase(action.id);state.road_actions.erase(action.id);state.rescues.set(action.id,{origin});if(draft){const auto* current=common.action(action.id);if(!current)return common_failure("TravelRescueReplacementActionRequired",action.id);draft->replacement_action=*current;}if(replacement)*replacement=std::move(draft);return common_success();}
// 按每个真实私有lot分别向下取十分之一，仅一次revision更新，公物和预留身份不改变。
Status finish_rescue(CommonWrite& common,TravelState& state,const TravelCatalog& catalog,const StableId& action_id,std::optional<TravelRescueCompletionDraft>* completion){if(completion)completion->reset();const auto* action=common.action(action_id);const auto* p=state.rescues.find(action_id);if(!action||!p)return common_failure("InvalidRescueAction");if(completion&&(action->kind!="rescue"||action->remaining_ticks!=0))return common_failure("TravelRescueCompletionBoundaryRequired",action_id);const auto* actor=common.actor(action->actor_id);if(!actor)return common_failure("UnknownActor");const auto* inventory=common.inventory(actor->inventory_id);const auto* settlement=catalog.settlements.find(p->origin);if(!inventory||!settlement)return common_failure("InvalidRescueAction");const StableId actor_id=action->actor_id,origin=p->origin,entry_place=settlement->entry_place;AdjustLots adjustment;adjustment.inventory_id=actor->inventory_id;Owner owner;owner.kind=Owner::Kind::actor;owner.id=actor->id;for(const auto& lot:inventory->lots)if(owner_equal(lot.owner,owner))adjustment.lots.push_back({lot.id,-lot.quantity/10});// 写前保原批与原损耗recipe，晚位置失败仍不给完成源，回滚归原外层候选。
    std::optional<TravelRescueCompletionDraft> draft;if(completion){draft.emplace();draft->action=*action;draft->source_tick=common.tick();draft->rescue=*p;draft->before_location=actor->location;draft->before_inventory=*inventory;draft->applied_adjustment=adjustment;}
    ResourceRecipe recipe;recipe.operations.push_back(std::move(adjustment));auto adjusted=common.apply_resources(recipe);if(!adjusted.ok)return adjusted;ActorMutation location;location.actor_id=actor_id;location.location=SettlementLocation{origin,entry_place};auto relocated=common.apply_actor(location);if(!relocated.ok)return relocated;if(draft){const auto* actual_actor=common.actor(actor_id);const auto* actual_inventory=common.inventory(draft->before_inventory.id);if(!actual_actor||!actual_inventory)return common_failure("TravelRescueCompletionSourceRequired",action_id);draft->after_location=actual_actor->location;draft->after_inventory=*actual_inventory;}if(completion)*completion=std::move(draft);return common_success();}
// 原本地准入顺序：目标、相邻通路、所有成员可用、所有成员条件，缺能力不能当准入。
Status preview_move_local(const CommonRead& common,const TravelCatalog& catalog,const TravelServices& services,const StableId& actor_id,const StableId& place_id){auto field=common.field_battle_bound(actor_id);if(!field.ok)return {false,{},field.error};if(field.value)return {false,{},common_failure("FieldBattleMovementBlocked",actor_id).error};const auto* target=catalog.places.find(place_id);if(!target)return common_failure("UnknownPlace");const auto* actor=common.actor(actor_id);const auto* here=actor?std::get_if<SettlementLocation>(&actor->location):nullptr;const auto* place=here?catalog.places.find(here->place_id):nullptr;if(!here||!place||std::find(place->passages.begin(),place->passages.end(),place_id)==place->passages.end())return common_failure("NoLocalPassage");auto fleet=services.vessel_fleet(actor_id);if(!fleet.ok)return {false,{},fleet.error};if(fleet.value&&(!services.naval_berth(here->place_id)||!services.naval_berth(place_id)))return common_failure("NavalLocalBerthRequired");const auto* members=common.members(actor_id);if(!members)return common_failure("ParticipantBusy");for(const auto& id:*members){const auto* a=common.actor(id);if(!a||!a->alive||!a->available||!a->action_id.empty())return common_failure("ParticipantBusy");}for(const auto& id:*members){auto admitted=services.admission_allowed(id,place_id);if(!admitted.ok)return {false,{},admitted.error};if(!admitted.value)return common_failure("AudienceDenied");}return common_success();}
// 这里只落位置；调用者紧接着清说话者会话和执行C on_enter，失败仍整事务回滚。
Status apply_move_local_location(CommonWrite& common,const TravelCatalog& catalog,const StableId& actor_id,const StableId& place_id){auto field=common.field_battle_bound(actor_id);if(!field.ok)return {false,{},field.error};if(field.value)return {false,{},common_failure("FieldBattleMovementBlocked",actor_id).error};const auto* target=catalog.places.find(place_id);if(!target)return common_failure("UnknownPlace");ActorMutation change;change.actor_id=actor_id;change.location=SettlementLocation{target->settlement_id,place_id};return common.apply_actor(change);}
// 中央释放共同action头时同步移除唯一业务payload；永久journey事实仍保留。
Status erase_travel_action_payload(TravelState& state,const StableId& action_id){state.actions.erase(action_id);state.road_actions.erase(action_id);state.rescues.erase(action_id);return common_success();}
} // 救援完成后的资源释放和action删除仍由中央按原顺序协调。
